import { useState } from 'react';
function StatefulBadge({ ticket }) {
  const [open, setOpen] = useState(false);
  return <button onClick={() => setOpen(!open)}>{ticket.status}: {String(open)}</button>;
}
export function TicketBadge({ ticket }) {
  if (!ticket) return null;
  return <StatefulBadge ticket={ticket} />;
}
